<script setup lang="ts">
defineProps<{order:any;role:string;busy:boolean}>();const emit=defineEmits(['update']);
const statuses:Record<string,string>={confirmed:'Confirmed',preparing:'Preparing',ready:'Ready',delivered:'Delivered',cancelled:'Cancelled'};
const paymentLabels:Record<string,string>={unpaid:'Awaiting payment',paid:'Paid',not_required:'No payment required'};
const nextStatus:Record<string,string>={confirmed:'preparing',preparing:'ready',ready:'delivered'};
const nextLabel:Record<string,string>={confirmed:'Start preparing',preparing:'Mark ready',ready:'Mark delivered'};
const money=(value:any)=>'Rs '+Number(value||0).toLocaleString('en-PK',{minimumFractionDigits:2,maximumFractionDigits:2});
</script>
<template><article class="canteen-order-card" :class="'order-'+order.status"><header class="canteen-order-card-header"><div class="canteen-order-number"><span>ORDER</span><h3>#{{order.id}}</h3></div><span class="canteen-order-status" :class="'status-'+order.status">{{statuses[order.status]||order.status}}</span></header><div class="canteen-order-person"><strong>{{order.employee_name}}</strong><time :datetime="order.created_at">{{new Date(order.created_at).toLocaleString(undefined,{month:'short',day:'numeric',hour:'numeric',minute:'2-digit'})}}</time></div><div class="canteen-order-items"><div v-for="line in order.lines" :key="line.id||line.item_name"><span>{{line.item_name}}</span><strong class="canteen-order-quantity">× {{line.quantity}}</strong></div><small>{{order.lines.reduce((sum:number,line:any)=>sum+Number(line.quantity),0)}} items</small></div><div v-if="role!=='kitchen'" class="canteen-order-payment"><div><small>Employee share</small><strong>{{money(order.employee_share)}}</strong></div><span class="canteen-payment-status" :class="'payment-'+order.payment_status">{{paymentLabels[order.payment_status]||order.payment_status}}</span></div><footer class="canteen-order-footer"><div class="canteen-order-primary-actions"><button v-if="['admin','kitchen'].includes(role)&&nextStatus[order.status]" class="button primary" :disabled="busy" @click="emit('update',order.id,{status:nextStatus[order.status]})">{{nextLabel[order.status]}}</button><button v-if="['admin','cashier'].includes(role)&&order.payment_status==='unpaid'&&order.status!=='cancelled'" class="button primary" :disabled="busy" @click="emit('update',order.id,{payment_status:'paid'})">Confirm cash received</button></div><div class="canteen-order-receipts"><a :href="'/canteen/orders/'+order.id+'/receipt/kitchen'" target="_blank" rel="noopener" :aria-label="'Kitchen receipt for order '+order.id"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" aria-hidden="true"><path d="M6 3h12v18l-3-2-3 2-3-2-3 2V3z M9 7h6 M9 11h6"/></svg>Kitchen receipt</a><a v-if="role!=='kitchen'" :href="'/canteen/orders/'+order.id+'/receipt/cashier'" target="_blank" rel="noopener" :aria-label="'Cashier receipt for order '+order.id"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" aria-hidden="true"><path d="M6 3h12v18l-3-2-3 2-3-2-3 2V3z M9 7h6 M9 11h6"/></svg>Cashier receipt</a><button v-if="['admin','cashier'].includes(role)&&['confirmed','preparing'].includes(order.status)&&order.payment_status!=='paid'" type="button" class="canteen-order-cancel" :disabled="busy" @click="emit('update',order.id,{status:'cancelled'})">Cancel order</button></div></footer></article></template>
